
import { QueryClient } from "@tanstack/react-query";
import { createRouter } from "@tanstack/react-router";

// This file is automatically generated by the TanStack Router Vite plugin.
// Do not edit routeTree.gen.ts manually.
import { routeTree } from "./routeTree.gen";

// ----------------------------------------------------
// FX QUEST - ROUTER CONFIGURATION
// ----------------------------------------------------
// Creates the client-side router for the independent
// React + Vite version of FX Quest.
//
// Preserves:
// - Welcome page navigation
// - Character selection
// - Adventure maps
// - Learning missions
// - Achievements
// - Browser back/forward navigation
// ----------------------------------------------------

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 60_000,
      retry: 1,
      refetchOnWindowFocus: false,
    },
  },
});

export const router = createRouter({
  routeTree,

  // Shared React Query client available to route loaders.
  context: {
    queryClient,
  },

  // Restore scroll position when navigating.
  scrollRestoration: true,

  // Avoid unnecessary route preload cache staleness.
  defaultPreloadStaleTime: 0,
});

// Enable type-safe TanStack Router navigation.
declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router;
  }
}
